create or replace package body apx_demo_sec_pkg as

   g_test_user varchar2(255);

   function package_version return varchar2
   is
   begin
      -- Version History:
      -- 01.00.00 2026-11-01 Tim PANDAWA  Generated by pandawa-apexlang
      return '01.00.00';
   end package_version;

   function app_user return varchar2
   is
   begin
      return upper(coalesce(g_test_user
                           ,sys_context('APEX$SESSION', 'APP_USER')
                           ,sys_context('USERENV', 'SESSION_USER')));
   end app_user;

   function bootstrap_mode return boolean
   is
      l_count number;
   begin
      select count(*)
        into l_count
        from apx_demo_user_roles
       where role_code = 'ADMIN';
      return l_count = 0;
   end bootstrap_mode;

   function has_role (
      p_role     in varchar2
     ,p_username in varchar2 default null
   ) return boolean
   is
      l_user  apx_demo_user_roles.username%type := upper(coalesce(p_username, app_user));
      l_count number;
   begin
      if bootstrap_mode then
         return true;
      end if;
      select count(*)
        into l_count
        from apx_demo_user_roles
       where username = l_user
         and role_code in (upper(p_role), 'ADMIN');
      return l_count > 0;
   end has_role;

   function has_role_yn (
      p_role     in varchar2
     ,p_username in varchar2 default null
   ) return varchar2
   is
   begin
      return case when has_role(p_role, p_username) then 'Y' else 'N' end;
   end has_role_yn;

   function has_any_role (
