create or replace force view apx_demo_request_summary_v as
select r.request_id
      ,r.request_no
      ,d.dept_name
      ,r.request_date
      ,r.purpose
      ,(select count(*) from apx_demo_request_lines l where l.request_id = r.request_id) line_count
